 const cityClocks=clockCities.map(([city,zone],index)=>({city,zone,time:clockStrip.children[index].querySelector('time'),date:clockStrip.children[index].querySelector('.clock-date'),timeFormat:new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}),dateFormat:new Intl.DateTimeFormat('en-GB',{timeZone:zone,weekday:'short',day:'numeric',month:'short'})}));
