 async function api(action,payload){const response=await fetch('/api/household?action='+encodeURIComponent(action),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':data.csrf},body:JSON.stringify(payload||{})});let result;try{result=await response.json();}catch{throw Error('The local server could not confirm the save.');}if(response.status===401){location.replace('/private-desk');throw Error('Session expired.');}if(!response.ok)throw Object.assign(Error(result.error||'Save failed.'),{status:response.status});return result;}
 async function load(){const generation=++requestGeneration;const response=await fetch('/api/household?resource=state'+(month?'&month='+encodeURIComponent(month):''),{cache:'no-store'});if(response.status===401){location.replace('/private-desk');return;}const result=await response.json();if(!response.ok)throw Error(result.error||'Unable to open the plan.');if(generation!==requestGeneration)return;data=result;month=data.month;$('#month').value=month;$('#month').min=data.settings.startMonth;$('#previous-month').disabled=month<=data.settings.startMonth;$('#save-count').textContent=data.localSaveCount+' recorded change'+(data.localSaveCount===1?'':'s');updateConnection();render();if(page==='overview')refreshInvestmentQuotes();}
