  const template=document.createElement('template');template.innerHTML=investmentPanel();const replacement=template.content.firstElementChild;replacement.querySelectorAll('details[data-market-detail]').forEach(d=>{d.open=opened.has(d.dataset.marketDetail);});panel.replaceWith(replacement);const newTable=replacement.querySelector('.etf-leaders .table-wrap');if(newTable){newTable.scrollTop=scrollTop;newTable.scrollLeft=scrollLeft;}
