  const feedWarnings=Object.entries(investmentState?.feedStatus||{}).filter(([,status])=>feedMessages[status]).map(([feed,status])=>`${feed==='finnhub'?'Finnhub / NVIDIA':feed==='london'?'London USD feed':'Xetra EUR feed'}: ${feedMessages[status]}`);
