 function assets(){return heading('A fuller picture,<br><em>one asset at a time.</em>','Purchase figures, ongoing costs and current valuations. Open an asset’s details for the full record.','asset','Add asset')+(data.assets.length?`<div class="cards-grid asset-register">${data.assets.map(assetCard).join('')}</div>`:'<div class="empty"><h2>Ready when you are.</h2><p>No asset balances or valuations have been recorded. Your monthly cash plan works independently of this register.</p><button class="secondary" data-new="asset">Add your first asset ↗</button></div>');}

