 document.addEventListener('input',event=>{if(event.target.id==='plan-search'){search=event.target.value;const start=event.target.selectionStart;render();$('#plan-search').focus();$('#plan-search').setSelectionRange(start,start);}});
 document.addEventListener('change',async event=>{if(event.target.dataset.actionId){const box=event.target,id=box.dataset.actionId;box.disabled=true;try{const result=await api('set-action-status',{revision:data.actions.revision,id,done:box.checked});data.actions=result.actions;if(page==='actions'){render();document.querySelector('[data-action-id="'+id+'"]')?.focus({preventScroll:true});}showToast('Checklist progress saved on this computer.');}catch(error){box.checked=!box.checked;showToast(error.message);if(error.status===409)await load().catch(()=>{});}finally{box.disabled=false;}return;}if(event.target.id==='kind-filter'){kindFilter=event.target.value;render();}if(event.target.id==='include-inactive'){includeInactive=event.target.checked;render();}});
