 let idleTimer;function resetIdle(){clearTimeout(idleTimer);idleTimer=setTimeout(()=>{location.replace('/private-desk');},15*60*1000);}for(const event of ['pointerdown','keydown'])document.addEventListener(event,resetIdle,{passive:true});resetIdle();
